//! The AMD shader ISAs as AMD's machine-readable ISA specification defines them (decisions D18),
//! generated by `isa-proc` from the vendored XML bundle, in their own crate so that the crates
//! using them do not regenerate them on every build: the hosts RDNA 3.5 (gfx11.5) and RDNA 4
//! (gfx12). The PS5 guest ISA (gfx1013) is decoded by hand.

/// One architecture.
#[derive(Debug)]
pub struct Isa {
    pub architecture: &'static str,
    pub encodings: &'static [Encoding],
    pub instructions: &'static [Instruction],
    /// The distinct operands, which [`InstructionEncoding::operands`] index.
    pub operands: &'static [Operand],
    /// The encoding conditions, which [`InstructionEncoding::condition`] indexes.
    pub conditions: &'static [&'static str],
    /// Functional group and subgroup names, which [`Instruction::group`] and
    /// [`Instruction::subgroups`] index.
    pub groups: &'static [&'static str],
    pub data_formats: &'static [DataFormat],
    pub operand_types: &'static [OperandType],
}

/// An instruction encoding (microcode format).
#[derive(Debug)]
pub struct Encoding {
    pub name: &'static str,
    /// Bits the encoding takes, literals and extra address dwords included.
    pub bits: u16,
    /// The bits that identify the encoding, low dword first.
    pub mask: &'static [u32],
    /// Values of the masked bits that select this encoding.
    pub identifiers: &'static [&'static [u32]],
    pub fields: &'static [Field],
}

/// A microcode field and its bit ranges, low bits first.
#[derive(Debug)]
pub struct Field {
    pub name: &'static str,
    /// Present only under some encoding condition.
    pub conditional: bool,
    pub ranges: &'static [BitRange],
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BitRange {
    pub offset: u16,
    pub bits: u16,
}

/// An instruction and its encoded forms.
#[derive(Debug)]
pub struct Instruction {
    /// Upper case, as the XML names it.
    pub name: &'static str,
    pub aliases: &'static [&'static str],
    /// [`flags`] bits.
    pub flags: u8,
    pub group: u8,
    pub subgroups: &'static [u8],
    pub encodings: &'static [InstructionEncoding],
}

/// [`Instruction::flags`] bits.
pub mod flags {
    pub const BRANCH: u8 = 1 << 0;
    pub const CONDITIONAL_BRANCH: u8 = 1 << 1;
    pub const INDIRECT_BRANCH: u8 = 1 << 2;
    pub const PROGRAM_TERMINATOR: u8 = 1 << 3;
    pub const IMMEDIATELY_EXECUTED: u8 = 1 << 4;
}

/// One encoded form of an instruction.
#[derive(Debug)]
pub struct InstructionEncoding {
    /// Index of the [`Encoding`] in [`Isa::encodings`].
    pub encoding: u8,
    /// Index in [`Isa::conditions`].
    pub condition: u8,
    pub opcode: u16,
    /// Indices in [`Isa::operands`], in the XML's operand order.
    pub operands: &'static [u16],
}

#[derive(Debug, Eq, PartialEq)]
pub struct Operand {
    /// The [`Field::name`] that holds it (empty for implicit operands).
    pub field: &'static str,
    pub data_format: &'static str,
    /// An [`OperandType::name`].
    pub kind: &'static str,
    /// Bits.
    pub size: u16,
    pub input: bool,
    pub output: bool,
    pub implicit: bool,
    /// Whether the encoding carries it.
    pub in_microcode: bool,
}

#[derive(Debug)]
pub struct DataFormat {
    pub name: &'static str,
    pub data_type: &'static str,
    pub bits: u16,
}

/// An operand type and the named values its field can hold.
#[derive(Debug)]
pub struct OperandType {
    pub name: &'static str,
    pub partitioned: bool,
    pub values: &'static [(&'static str, i64)],
}

impl Isa {
    /// The instruction named `name`, upper case, directly or as an alias.
    pub fn instruction(&self, name: &str) -> Option<&Instruction> {
        self.instructions
            .iter()
            .find(|instruction| instruction.name == name || instruction.aliases.contains(&name))
    }

    /// The encoding named `name`.
    pub fn encoding(&self, name: &str) -> Option<&Encoding> {
        self.encodings.iter().find(|encoding| encoding.name == name)
    }

    /// The encoding of `form`.
    pub fn encoding_of(&self, form: &InstructionEncoding) -> &Encoding {
        &self.encodings[usize::from(form.encoding)]
    }

    /// The operands of `form`, in order.
    pub fn operands_of<'a>(&'a self, form: &'a InstructionEncoding) -> impl Iterator<Item = &'a Operand> + 'a {
        form.operands.iter().map(|&index| &self.operands[usize::from(index)])
    }
}

isa_proc::isa!(rdna3_5 in crate);
isa_proc::isa!(rdna4 in crate);
